import java.math.BigDecimal;

// Adaptee: SDK fechada do gateway de cartão
class SdkPagamentoCredito {
    public void autorizar(BigDecimal valor) {
        System.out.println("SDK: autorizando R$" + valor);
    }
    public void capturar(BigDecimal valor) {
        System.out.println("SDK: capturando R$" + valor);
    }
    public void creditar(BigDecimal valor) {
        System.out.println("SDK: creditando R$" + valor);
    }
}

// Target: contrato que o sistema de checkout espera
interface ProcessorPagamento {
    void debitar(BigDecimal valor);
    void creditar(BigDecimal valor);
}

// Adapter: traduz o vocabulário do sistema para o vocabulário da SDK
class MeuPagamentoCredito implements ProcessorPagamento {
    private final SdkPagamentoCredito sdk;

    public MeuPagamentoCredito(SdkPagamentoCredito sdk) {
        this.sdk = sdk;
    }

    @Override
    public void debitar(BigDecimal valor) {
        sdk.autorizar(valor);
        sdk.capturar(valor);
    }

    @Override
    public void creditar(BigDecimal valor) {
        sdk.creditar(valor);
    }
}

// Outro Adapter para um gateway diferente — mesmo contrato, outra tradução
class MeuPagamentoPix implements ProcessorPagamento {
    @Override
    public void debitar(BigDecimal valor) {
        System.out.println("Pix: transferindo R$" + valor);
    }

    @Override
    public void creditar(BigDecimal valor) {
        System.out.println("Pix: devolvendo R$" + valor);
    }
}

// Client: não sabe qual gateway está por baixo
public class Main {
    static void processar(ProcessorPagamento pagamento, BigDecimal valor) {
        pagamento.debitar(valor);
    }

    public static void main(String[] args) {
        BigDecimal valor = new BigDecimal("150.00");

        ProcessorPagamento cartao = new MeuPagamentoCredito(new SdkPagamentoCredito());
        processar(cartao, valor);

        ProcessorPagamento pix = new MeuPagamentoPix();
        processar(pix, valor);
    }
}
